module multi_pipe_4bit(
    input clk, 
    input rst_n, 
    input [3:0] mul_a, 
    input [3:0] mul_b, 
    output [7:0] mul_out
);

// TODO: Please add your solution here

	parameter size = 4;

	reg [7:0] mul_a_ext, mul_b_ext;
	reg [7:0] partial_product[3:0];
	reg [7:0] sum_reg[3:0];
	reg [7:0] product_reg;
	integer j;

	assign mul_a_ext = {4'b0, mul_a};
	assign mul_b_ext = {4'b0, mul_b};


	generate
	for(genvar i = 0 ; i<size ; i=i+1) begin : gen_partial_products
		assign partial_product[i] = (mul_b_ext[i]) ? (mul_a_ext << i) : 'd0;
	end

	endgenerate

	//stage 1
	always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		sum_reg[0] <= 8'd0;
		sum_reg[1] <= 8'd0;
		sum_reg[2] <= 8'd0;
		sum_reg[3] <= 8'd0;

	end
	else begin
		sum_reg[0] <= partial_product[0];
		sum_reg[1] <= partial_product[1];
		sum_reg[2] <= partial_product[2];
		sum_reg[3] <= partial_product[3];
	end
	end

	//stage 2
	always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		product_reg <= 8'd0;
	end
	else begin
		product_reg <= sum_reg[0] + sum_reg[1] + sum_reg[2] + sum_reg[3];
	end
	end

	assign mul_out = product_reg;
endmodule
